import type { BeeMemoryFact, ScenarioId } from "../shared/types";
import { SCENARIOS } from "./scenarios";

/**
 * Bee's local proxy (`bee proxy`) exposes spoken memory at :8787. The proxy is
 * optional: a recorded household fixture keeps the demo deterministic when the
 * daemon or a physical Bee is not present.
 */
export async function fetchBeeAmbientContext(scenarioId: ScenarioId): Promise<BeeMemoryFact> {
  const scenario = SCENARIOS[scenarioId];
  const fallback: BeeMemoryFact = {
    id: `bee_fact_${scenarioId.toLowerCase()}`,
    timestamp: scenario.beeFact.capturedAt,
    speaker: scenario.beeFact.speaker,
    transcriptSnippet: scenario.beeFact.quote.replace(/[“”]/g, ""),
    extractedCommitment: scenario.beeFact.commitment,
    source: "bee_recorded_session_fixture"
  };

  const proxyUrl = process.env.BEE_PROXY_URL;
  if (!proxyUrl) return fallback;

  try {
    const response = await fetch(`${proxyUrl}?scenario=${encodeURIComponent(scenarioId)}`, {
      signal: AbortSignal.timeout(400),
      headers: { Accept: "application/json" }
    });
    if (!response.ok) return fallback;

    const data = (await response.json()) as Partial<BeeMemoryFact> & {
      facts?: Array<Partial<BeeMemoryFact>>;
    };
    const candidate = data.facts?.[0] ?? data;
    if (
      typeof candidate.extractedCommitment === "string" &&
      candidate.extractedCommitment.trim().length > 0
    ) {
      return {
        id: candidate.id ?? fallback.id,
        timestamp: candidate.timestamp ?? fallback.timestamp,
        speaker: candidate.speaker ?? fallback.speaker,
        transcriptSnippet: candidate.transcriptSnippet ?? fallback.transcriptSnippet,
        extractedCommitment: candidate.extractedCommitment,
        source: "bee_cli_live_proxy"
      };
    }
  } catch {
    // A missing Bee daemon is an expected offline state, not a failure.
  }

  return fallback;
}

import {
  BedrockRuntimeClient,
  InvokeModelCommand
} from "@aws-sdk/client-bedrock-runtime";
import type { AlexaMcpAppCard, AgentTrace, ScenarioId } from "../shared/types";
import { fetchBeeAmbientContext } from "./beeContextClient";
import { SCENARIOS } from "./scenarios";

export const DEFAULT_MODEL_ID = process.env.BEDROCK_MODEL_ID || "amazon.nova-pro-v1:0";

export function hasBedrockCredentials(): boolean {
  return Boolean(process.env.AWS_ACCESS_KEY_ID && process.env.AWS_SECRET_ACCESS_KEY);
}

function buildCard(scenarioId: ScenarioId, spokenAlexaPrompt: string, beeContextFact: string): AlexaMcpAppCard {
  const scenario = SCENARIOS[scenarioId];
  return {
    type: "AlexaMcpAppCard",
    version: "2025-11-25",
    scenarioId,
    severity: scenario.severity,
    title: scenario.title,
    subtitle: scenario.summary.split(". ")[0] + ".",
    spokenAlexaPrompt,
    beeContextFact,
    evidence: scenario.evidence,
    captions: scenario.captions,
    fireTvHudActions: scenario.hudActions.map(({ id, label, dpadKey, alexaCommand, spokenResponse, outcome }) => ({
      id,
      label,
      dpadKey,
      alexaCommand,
      spokenResponse,
      outcome
    }))
  };
}

function safeLiveSentence(text: string): string {
  return text
    .replace(/^["'`]+|["'`]+$/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 420);
}

async function invokeNova(
  scenarioId: ScenarioId,
  beeContext: string
): Promise<string | undefined> {
  const scenario = SCENARIOS[scenarioId];
  const client = new BedrockRuntimeClient({
    region: process.env.AWS_REGION || "us-east-1"
  });

  const prompt = [
    "You are HearthGuard, a calm care concierge speaking through an Alexa+ device.",
    "Write one short spoken intervention (max 55 words) for this threshold moment.",
    "Be specific, warm, and non-alarming. Do not mention cameras, models, or monitoring.",
    `Situation: ${scenario.title} ${scenario.summary}`,
    `Household memory: ${beeContext}`,
    "Return only the sentence to speak."
  ].join("\n");

  const command = new InvokeModelCommand({
    modelId: DEFAULT_MODEL_ID,
    contentType: "application/json",
    accept: "application/json",
    body: JSON.stringify({
      messages: [{ role: "user", content: [{ text: prompt }] }],
      inferenceConfig: {
        max_new_tokens: 180,
        temperature: 0.2,
        top_p: 0.9
      }
    })
  });

  const response = await client.send(command, {
    abortSignal: AbortSignal.timeout(7000)
  });

  const decoded = JSON.parse(new TextDecoder().decode(response.body)) as {
    output?: { message?: { content?: Array<{ text?: string }> } };
  };
  const text = decoded.output?.message?.content?.[0]?.text;
  return text ? safeLiveSentence(text) : undefined;
}

export async function runBedrockStrandsThresholdAgent(
  scenarioId: ScenarioId
): Promise<AgentTrace> {
  const startedAt = performance.now();
  const scenario = SCENARIOS[scenarioId];
  const beeMemory = await fetchBeeAmbientContext(scenarioId);
  let inferenceMode: AgentTrace["inferenceMode"] = "deterministic_recorded_trace";
  let spoken = scenario.spokenAlexaPrompt;

  if (hasBedrockCredentials()) {
    try {
      const live = await invokeNova(scenarioId, beeMemory.extractedCommitment);
      if (live) {
        spoken = live;
        inferenceMode = "aws_bedrock_live";
      }
    } catch {
      // Entitlement, region, or network failure: keep the demo usable.
      inferenceMode = "deterministic_recorded_trace";
    }
  }

  const latencyMs = Math.round((performance.now() - startedAt) * 100) / 100;
  const steps = [
    `Bee · recalled ${beeMemory.source === "bee_cli_live_proxy" ? "live proxy" : "recorded"} memory — “${beeMemory.extractedCommitment}”`,
    `Nova · fused Ring threshold + household memory (${inferenceMode === "aws_bedrock_live" ? "live" : "recorded trace"}, ${latencyMs} ms)`,
    `Policy · selected a ${scenario.severity === "CRITICAL_CARE" ? "gentle redirect" : scenario.severity === "ACCESSIBILITY_RELAY" ? "visual relay" : "timed custody"} response`,
    "Alexa+ · built a card with three D-pad actions for the Fire TV"
  ];

  return {
    scenarioId,
    modelId: DEFAULT_MODEL_ID,
    inferenceMode,
    latencyMs,
    beeMemory,
    steps,
    card: buildCard(scenarioId, spoken, beeMemory.extractedCommitment)
  };
}

import { EventEmitter } from "node:events";
import type { SseEvent } from "../shared/types";

class CareEventBus {
  private readonly emitter = new EventEmitter();

  constructor() {
    this.emitter.setMaxListeners(40);
  }

  publish(type: SseEvent["type"], data: unknown): SseEvent {
    const event: SseEvent = {
      type,
      at: new Date().toISOString(),
      data
    };
    this.emitter.emit("event", event);
    return event;
  }

  subscribe(listener: (event: SseEvent) => void): () => void {
    this.emitter.on("event", listener);
    return () => this.emitter.off("event", listener);
  }
}

export const careEvents = new CareEventBus();

import type { ScenarioId, TimelineEntry, TimelineKind } from "../shared/types";

const MAX_ENTRIES = 120;
const entries: TimelineEntry[] = [];

export function addTimeline(
  kind: TimelineKind,
  title: string,
  detail: string,
  scenarioId?: ScenarioId
): TimelineEntry {
  const entry: TimelineEntry = {
    id: `tl_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 7)}`,
    at: new Date().toISOString(),
    kind,
    title,
    detail,
    scenarioId
  };
  entries.push(entry);
  if (entries.length > MAX_ENTRIES) entries.splice(0, entries.length - MAX_ENTRIES);
  return entry;
}

export function listTimeline(): TimelineEntry[] {
  return [...entries];
}

export function clearTimeline(): void {
  entries.length = 0;
}

import type { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";

/** Live MCP Streamable HTTP sessions, keyed by `Mcp-Session-Id`. */
export const mcpSessions = new Map<string, StreamableHTTPServerTransport>();

export function mcpSessionCount(): number {
  return mcpSessions.size;
}

import { LATEST_PROTOCOL_VERSION } from "@modelcontextprotocol/sdk/types.js";
import {
  negotiateRingWhepSession,
  type WhepSessionResult
} from "../../packages/ring-alexa-mcp-bridge/src/index";
import type {
  CareIncident,
  CapabilityReport,
  IncidentSource,
  InterventionResult,
  ScenarioId,
  ServerState,
  TimelineEntry
} from "../shared/types";
import { hasBedrockCredentials, runBedrockStrandsThresholdAgent } from "./bedrockStrandsAgent";
import { careEvents } from "./eventBus";
import { mcpSessionCount } from "./mcpSessions";
import { SCENARIOS } from "./scenarios";
import { addTimeline, clearTimeline, listTimeline } from "./timeline";

const WEBHOOK_SECRET =
  process.env.RING_WEBHOOK_SECRET || "hearthguard_local_demo_secret_change_me";
const RING_API_BASE_URL = process.env.RING_API_BASE_URL || "https://api.amazonvision.com";
const RING_OAUTH_TOKEN = process.env.RING_OAUTH_TOKEN;
const DEMO_MODE = process.env.DEMO_MODE !== "false";

const SDP_OFFER = [
  "v=0",
  "o=- 0 2 IN IP4 127.0.0.1",
  "s=HearthGuard Fire TV",
  "t=0 0",
  "a=group:BUNDLE 0",
  "m=video 9 UDP/TLS/RTP/SAVPF 96",
  "c=IN IP4 0.0.0.0",
  "a=mid:0",
  "a=sendonly",
  "a=rtcp-mux",
  "a=rtpmap:96 H264/90000",
  ""
].join("\r\n");

const incidents = new Map<ScenarioId, CareIncident>();
const inFlight = new Map<ScenarioId, Promise<CareIncident>>();

export function webhookSecret(): string {
  return WEBHOOK_SECRET;
}

export function demoMode(): boolean {
  return DEMO_MODE;
}

export function capabilities(): CapabilityReport {
  return {
    mcpProtocol: LATEST_PROTOCOL_VERSION,
    mcpSessions: mcpSessionCount(),
    hmac: WEBHOOK_SECRET ? "verified" : "unconfigured",
    bedrock: hasBedrockCredentials() ? "live" : "replay",
    bee: process.env.BEE_PROXY_URL ? "proxy" : "fixture",
    whep: RING_OAUTH_TOKEN ? "live" : "simulator",
    demoMode: DEMO_MODE
  };
}

async function negotiateWhep(deviceId: string): Promise<WhepSessionResult> {
  if (RING_OAUTH_TOKEN) {
    try {
      return await negotiateRingWhepSession(deviceId, SDP_OFFER, {
        bearerToken: RING_OAUTH_TOKEN,
        baseUrl: RING_API_BASE_URL,
        timeoutMs: 6000
      });
    } catch {
      // Fall through to the loopback answer; the incident still needs to land.
    }
  }
  return negotiateRingWhepSession(deviceId, SDP_OFFER);
}

export async function processScenario(
  scenarioId: ScenarioId,
  source: IncidentSource = "demo"
): Promise<CareIncident> {
  const running = inFlight.get(scenarioId);
  if (running) return running;

  const task = (async (): Promise<CareIncident> => {
    const scenario = SCENARIOS[scenarioId];
    const whep = await negotiateWhep(scenario.deviceId);
    const trace = await runBedrockStrandsThresholdAgent(scenarioId);

    const incident: CareIncident = {
      id: `inc_${scenarioId.toLowerCase()}_${Date.now().toString(36)}`,
      scenarioId,
      status: "active",
      startedAt: new Date().toISOString(),
      source,
      scenario,
      card: trace.card,
      trace,
      whep: {
        mode: whep.mode,
        sessionId: whep.sessionId,
        endpoint: whep.whepEndpoint
      }
    };

    incidents.set(scenarioId, incident);

    addTimeline(
      "detected",
      `Ring · ${scenario.eyebrow.toLowerCase()} at the threshold`,
      `${scenario.deviceId} · ${source === "ring_webhook" ? "HMAC-verified webhook" : "signed replay webhook"} · WHEP ${whep.mode === "live_partner_api" ? "live" : "simulator"}`
    );
    addTimeline("reasoned", `Nova · ${scenario.intent.toLowerCase()}`, trace.steps[1] ?? trace.steps[0] ?? "Reasoning complete");
    addTimeline(
      "dispatched",
      "Alexa+ · card dispatched to Fire TV",
      `${scenario.hudActions.length} D-pad actions · room tone ducked to 20%`,
      scenarioId
    );

    careEvents.publish("incident.created", incident);
    careEvents.publish("timeline.updated", listTimeline());
    return incident;
  })();

  inFlight.set(scenarioId, task);
  try {
    return await task;
  } finally {
    inFlight.delete(scenarioId);
  }
}

export async function executeIntervention(
  scenarioId: ScenarioId,
  actionId: string
): Promise<InterventionResult> {
  const scenario = SCENARIOS[scenarioId];
  const action = scenario.hudActions.find((candidate) => candidate.id === actionId);
  if (!action) {
    throw new Error(`Unknown action "${actionId}" for ${scenarioId}`);
  }

  let incident = incidents.get(scenarioId);
  if (!incident) incident = await processScenario(scenarioId, "mcp");
  if (incident.status === "resolved") {
    incident = { ...incident, status: "active" };
    incidents.set(scenarioId, incident);
  }

  const at = new Date().toISOString();
  addTimeline("action", `Fire TV · ${action.shortLabel}`, action.outcome, scenarioId);
  careEvents.publish("intervention.executed", {
    incidentId: incident.id,
    scenarioId,
    actionId,
    spokenResponse: action.spokenResponse,
    outcome: action.outcome,
    at
  });
  careEvents.publish("timeline.updated", listTimeline());

  return {
    ok: true,
    actionId,
    spokenResponse: action.spokenResponse,
    outcome: action.outcome,
    at
  };
}

export function dispatchHud(scenarioId: ScenarioId): CareIncident {
  const incident = incidents.get(scenarioId);
  if (!incident) throw new Error(`No active incident for ${scenarioId}`);
  careEvents.publish("hud.dispatched", {
    incidentId: incident.id,
    scenarioId,
    card: incident.card
  });
  return incident;
}

export function resolveIncident(scenarioId: ScenarioId, note?: string): CareIncident {
  const incident = incidents.get(scenarioId);
  if (!incident) throw new Error(`No incident to resolve for ${scenarioId}`);
  if (incident.status === "resolved") return incident;

  const resolved: CareIncident = { ...incident, status: "resolved" };
  incidents.set(scenarioId, resolved);
  addTimeline(
    "resolved",
    `Care note · ${incident.scenario.eyebrow.toLowerCase()} closed`,
    note?.trim() || "Incident acknowledged and closed from the Fire TV.",
    scenarioId
  );
  careEvents.publish("incident.resolved", resolved);
  careEvents.publish("timeline.updated", listTimeline());
  return resolved;
}

export function getState(): ServerState {
  return {
    incidents: [...incidents.values()].sort((a, b) => b.startedAt.localeCompare(a.startedAt)),
    timeline: listTimeline(),
    capabilities: capabilities(),
    serverTime: new Date().toISOString()
  };
}

export function resetDemo(): ServerState {
  incidents.clear();
  inFlight.clear();
  clearTimeline();
  careEvents.publish("state.reset", null);
  return getState();
}

export function getIncident(scenarioId: ScenarioId): CareIncident | undefined {
  return incidents.get(scenarioId);
}

export function getTimeline(): TimelineEntry[] {
  return listTimeline();
}

