177: export async function negotiateRingWhepSession(
178:   deviceId: string,
179:   sdpOffer: string,
180:   bearerTokenOrOptions: string | WhepSessionOptions = {}
181: ): Promise<WhepSessionResult> {
182:   const options: WhepSessionOptions =
183:     typeof bearerTokenOrOptions === "string"
184:       ? { bearerToken: bearerTokenOrOptions }
185:       : bearerTokenOrOptions;
186: 
187:   if (!deviceId.trim()) throw new Error("deviceId is required");
188:   if (!sdpOffer.includes("v=0")) throw new Error("A valid SDP offer is required");
189: 
190:   const baseUrl = (options.baseUrl ?? "https://api.amazonvision.com").replace(/\/+$/, "");
191:   const endpoint = `${baseUrl}/v1/devices/${encodeURIComponent(
192:     deviceId
193:   )}/media/streaming/whep/sessions`;
194: 
195:   if (!options.bearerToken || options.bearerToken === SIMULATOR_TOKEN) {
196:     return loopbackAnswer(deviceId);
197:   }
198: 
199:   const fetchImpl = options.fetchImpl ?? fetch;
200:   const signal =
201:     typeof AbortSignal !== "undefined" && "timeout" in AbortSignal
202:       ? AbortSignal.timeout(options.timeoutMs ?? 8000)
203:       : undefined;
204: 
205:   const response = await fetchImpl(endpoint, {
206:     method: "POST",
207:     headers: {
208:       Authorization: `Bearer ${options.bearerToken}`,
209:       "Content-Type": "application/sdp",
210:       Accept: "application/sdp"
211:     },
212:     body: sdpOffer,
213:     signal
214:   });
215: 
216:   if (response.status !== 201 && response.status !== 200) {
217:     throw new WhepNegotiationError(
218:       `WHEP negotiation failed with HTTP ${response.status}`,
219:       response.status
220:     );
221:   }
222: 
223:   const sdpAnswer = await response.text();
224:   const location = response.headers.get("location");
225:   const resolvedLocation = location ? new URL(location, endpoint).toString() : endpoint;
226:   const sessionId =
227:     response.headers.get("x-whep-session-id") ??
228:     resolvedLocation.split("/").filter(Boolean).pop() ??
229:     crypto.randomUUID();
230: 
231:   return {
232:     sessionId,
233:     whepEndpoint: resolvedLocation,
234:     sdpAnswer,
235:     mode: "live_partner_api"
236:   };
237: }
