import { SCENARIOS, SCENARIO_ORDER } from "../../server/scenarios";
import type {
  CareIncident,
  InterventionResult,
  ScenarioDefinition,
  ScenarioId
} from "../../shared/types";
import {
  formatStamp,
  scenarioLabel,
  severityLabel,
  severityTone,
  sourceLabel
} from "../lib/format";
import { Glyph } from "./Glyph";
import { PaneHeader } from "./PaneHeader";

interface ReadingPaneProps {
  incident: CareIncident | null;
  scenario: ScenarioDefinition;
  loading: boolean;
  lastAction: InterventionResult | null;
  busyScenario: ScenarioId | null;
  onRun: (id: ScenarioId) => void;
  onResolve: () => void;
}

export function ReadingPane({
  incident,
  scenario,
  loading,
  lastAction,
  busyScenario,
  onRun,
  onResolve
}: ReadingPaneProps) {
  const meta = incident
    ? `${incident.trace.modelId.split(".").slice(-1)[0] ?? "Nova"} · ${
        incident.trace.inferenceMode === "aws_bedrock_live" ? "live" : "recorded trace"
      }`
    : "Nova · replay";

  return (
    <section className="pane pane--reading" aria-labelledby="reading-heading">
      <PaneHeader id="reading-heading" index="02" title="The reading" meta={meta} />

      {loading && !incident ? (
        <div className="reading-skeleton" aria-busy="true" aria-label="Loading the care reading">
          <span className="skeleton skeleton--eyebrow" />
          <span className="skeleton skeleton--title" />
          <span className="skeleton skeleton--title skeleton--short" />
          <span className="skeleton skeleton--line" />
          <span className="skeleton skeleton--line" />
          <span className="skeleton skeleton--line skeleton--short" />
          <span className="skeleton skeleton--block" />
        </div>
      ) : !incident ? (
        <div className="reading-empty">
          <p className="eyebrow">Standby · night watch</p>
          <h3 className="reading-empty__title">The house is quiet.</h3>
          <p className="reading-empty__body">
            No one is at the threshold. Choose a replay to watch Ring vision, Bee memory and
            Alexa+ resolve a care moment together.
          </p>
          <div className="reading-choices">
            {SCENARIO_ORDER.map((id) => {
              const item = SCENARIOS[id];
              const busy = busyScenario === id;
              return (
                <button
                  key={id}
                  type="button"
                  className={`choice ${busy ? "is-busy" : ""}`}
                  onClick={() => onRun(id)}
                  disabled={busyScenario !== null && busyScenario !== id}
                >
                  <span className="choice__num">{item.number}</span>
                  <span className="choice__copy">
                    <strong>{scenarioLabel(id)}</strong>
                    <span>
                      {item.time} {item.period} · {item.eyebrow}
                    </span>
                  </span>
                  <Glyph name="arrow" size={15} />
                </button>
              );
            })}
          </div>
          <p className="reading-empty__note">
            The default replay is the 2:15 AM night exit. Press 1, 2 or 3 on the care card to
            act once it arrives.
          </p>
        </div>
      ) : (
        <article className="reading" key={incident.id}>
          <div className="reading__eyebrow">
            <span className={`severity severity--${severityTone(scenario.severity)}`}>
              {severityLabel(scenario.severity)}
            </span>
            <span className="mono">
              {incident.scenarioId} · {sourceLabel(incident.source)}
            </span>
          </div>

          <h3 className="reading__title">{scenario.title}</h3>
          <p className="reading__summary">{scenario.summary}</p>

          <dl className="reading-facts">
            <div>
              <dt>Resident</dt>
              <dd>{scenario.resident}</dd>
            </div>
            <div>
              <dt>Intent</dt>
              <dd>{scenario.intent}</dd>
            </div>
            <div>
              <dt>Opened</dt>
              <dd>{formatStamp(incident.startedAt)}</dd>
            </div>
          </dl>

          <section className="reading-block memory" aria-labelledby="memory-heading">
            <div className="section-label">
              <span id="memory-heading">Remembered · Bee</span>
              <span>
                {incident.trace.beeMemory.source === "bee_cli_live_proxy"
                  ? "live proxy"
                  : "recorded fixture"}
              </span>
            </div>
            <blockquote className="memory__quote">
              <p>{scenario.beeFact.quote}</p>
              <footer>
                <span>{scenario.beeFact.speaker}</span>
                <time dateTime={scenario.beeFact.capturedAt}>
                  {formatStamp(scenario.beeFact.capturedAt)}
                </time>
              </footer>
            </blockquote>
            <p className="memory__commitment">{scenario.beeFact.commitment}</p>
          </section>

          <section className="reading-block trace" aria-labelledby="trace-heading">
            <div className="section-label">
              <span id="trace-heading">Reasoning trace</span>
              <span
                title="Local pipeline time for this replay. This is not a model benchmark."
              >
                {incident.trace.latencyMs.toFixed(2)} ms pipeline
              </span>
            </div>
            <ol className="trace__list">
              {incident.trace.steps.map((step, index) => {
                const parts = step.split(" · ");
                const actor = parts[0] ?? "Step";
                const text = parts.length > 1 ? parts.slice(1).join(" · ") : step;
                return (
                  <li className="trace__item" key={`${index}-${actor}`}>
                    <span className="trace__index">{String(index + 1).padStart(2, "0")}</span>
                    <span className="trace__actor">{actor}</span>
                    <span className="trace__text">{text}</span>
                  </li>
                );
              })}
            </ol>
          </section>

          <section className="reading-block voice" aria-labelledby="voice-heading">
            <div className="section-label">
              <span id="voice-heading">Alexa+ voice</span>
              <span>spoken response</span>
            </div>
            <blockquote className="voice__quote">
              “{incident.trace.card.spokenAlexaPrompt}”
            </blockquote>
          </section>

          {lastAction ? (
            <div className="action-result" role="status">
              <span className="action-result__icon" aria-hidden="true">
                <Glyph name="check" size={16} />
              </span>
              <div>
                <span className="section-label">
                  <span>Alexa+ · last action</span>
                  <span>{formatStamp(lastAction.at)}</span>
                </span>
                <p className="action-result__voice">“{lastAction.spokenResponse}”</p>
                <p className="action-result__outcome">{lastAction.outcome}</p>
              </div>
            </div>
          ) : null}

          <button type="button" className="button button--quiet reading__resolve" onClick={onResolve}>
            Write care note & close
            <Glyph name="enter" size={15} />
          </button>
        </article>
      )}
    </section>
  );
}

import { useEffect, useRef } from "react";
import type { WireEntry } from "../../shared/types";
import { formatTimecode, shortId } from "../lib/format";
import { Glyph } from "./Glyph";

interface McpWireProps {
  entries: WireEntry[];
  sessionId: string | null;
  connected: boolean;
  protocol: string;
  onReset: () => void;
}

const directionLabel: Record<WireEntry["direction"], string> = {
  out: "sent",
  in: "received",
  note: "note"
};

export function McpWire({ entries, sessionId, connected, protocol, onReset }: McpWireProps) {
  const listRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const element = listRef.current;
    if (!element) return;
    const nearBottom =
      element.scrollHeight - element.scrollTop - element.clientHeight < 140;
    if (nearBottom) element.scrollTop = element.scrollHeight;
  }, [entries.length]);

  return (
    <section className="ledger-panel wire" aria-labelledby="wire-heading">
      <header className="ledger-panel__head">
        <div className="ledger-panel__title">
          <span className="section-label section-label--inline">
            <span id="wire-heading">MCP wire</span>
          </span>
          <span className={`live ${connected ? "is-live" : "is-polling"}`}>
            <span className="live__dot" aria-hidden="true" />
            {connected ? "Streamable HTTP" : "Polling fallback"}
          </span>
        </div>
        <div className="ledger-panel__meta">
          <span className="chip chip--mono">{protocol}</span>
          <span className="chip chip--session" title={sessionId ?? undefined}>
            {shortId(sessionId, 10)}
          </span>
          <button type="button" className="icon-button" onClick={onReset} title="Reset the replay">
            <Glyph name="reset" size={14} />
            <span>Reset</span>
          </button>
        </div>
      </header>

      <div className="wire__list" ref={listRef} role="log" aria-live="polite" aria-relevant="additions">
        {entries.length === 0 ? (
          <p className="wire__empty">
            The wire is quiet. Start a replay to watch the MCP handshake and tool calls.
          </p>
        ) : (
          entries.map((entry) => (
            <div className={`wire__row wire__row--${entry.direction}`} key={entry.id}>
              <time className="wire__time" dateTime={entry.at}>
                {formatTimecode(entry.at)}
              </time>
              <span className="wire__dir" aria-label={directionLabel[entry.direction]}>
                {entry.direction === "out" ? "→" : entry.direction === "in" ? "←" : "·"}
              </span>
              <span className="wire__method">{entry.method}</span>
              <span className="wire__detail">{entry.detail}</span>
              {entry.status !== undefined ? (
                <span className={`wire__status ${entry.status >= 400 ? "is-error" : ""}`}>
                  {entry.status}
                </span>
              ) : (
                <span className="wire__status wire__status--none" aria-hidden="true">
                  —
                </span>
              )}
              <span className="wire__latency">
                {entry.latencyMs !== undefined ? `${entry.latencyMs.toFixed(1)} ms` : ""}
              </span>
            </div>
          ))
        )}
      </div>
    </section>
  );
}

import { useEffect, useRef } from "react";
import type { TimelineEntry } from "../../shared/types";
import { formatTimecode } from "../lib/format";

interface CareTimelineProps {
  entries: TimelineEntry[];
}

export function CareTimeline({ entries }: CareTimelineProps) {
  const listRef = useRef<HTMLOListElement>(null);

  useEffect(() => {
    const element = listRef.current;
    if (!element) return;
    element.scrollTop = element.scrollHeight;
  }, [entries.length]);

  return (
    <section className="ledger-panel timeline" aria-labelledby="timeline-heading">
      <header className="ledger-panel__head">
        <div className="ledger-panel__title">
          <span className="section-label section-label--inline">
            <span id="timeline-heading">Care timeline</span>
          </span>
          <span className="chip chip--tiny">{entries.length} notes</span>
        </div>
        <div className="ledger-panel__meta">
          <span className="mono">care://timeline</span>
        </div>
      </header>

      <ol className="timeline__list" ref={listRef}>
        {entries.length === 0 ? (
          <li className="timeline__empty">
            Nothing written yet. A care note appears here when an incident is detected,
            dispatched, acted on, or closed.
          </li>
        ) : (
          entries.map((entry) => (
            <li className={`timeline__item timeline__item--${entry.kind}`} key={entry.id}>
              <span className="timeline__rail" aria-hidden="true">
                <span className="timeline__dot" />
              </span>
              <time className="timeline__time" dateTime={entry.at}>
                {formatTimecode(entry.at)}
              </time>
              <div className="timeline__body">
                <h3 className="timeline__title">{entry.title}</h3>
                <p className="timeline__detail">{entry.detail}</p>
              </div>
              {entry.scenarioId ? (
                <span className="chip chip--tiny timeline__scenario">{entry.scenarioId}</span>
              ) : null}
            </li>
          ))
        )}
      </ol>
    </section>
  );
}

content.text:
It's fine; the tool output was just visually truncated. Good.

Now ActionDeck, Remote, HUD, TvStage.

Let me write `ActionDeck.tsx`:
Props:
```ts
interface ActionDeckProps {
  scenario: ScenarioDefinition;
  incident: CareIncident;
  navigation: TvNavigation;
  executingAction: string | null;
  lastAction: InterventionResult | null;
  onAction: (id: string) => void;
  onResolve: () => void;
}
```
Use navigation.registerAction. Note `navigation.index` is index into actions. `onFocus` setIndex.

Markup:
```tsx
<div className="deck">
  <div className="deck__head">
    <span className="section-label section-label--inline"><span>Alexa+ care card</span></span>
    <span className="deck__sev">{severityLabel}</span>
  </div>
  <div className="deck__actions">
    {scenario.hudActions.map((action, index) => {
      const active = navigation.index === index;
      const executing = executingAction === action.id;
      const done = lastAction?.actionId === action.id;
      return (
        <button ... className={`deck__action ${active?"is-active":""} ${done?"is-done":""}`} onFocus={() => navigation.setIndex(index)} onClick={() => onAction(action.id)} ref={navigation.registerAction(index)} disabled={executingAction !== null}>
          <span className="deck__key">{action.dpadKey}</span>
          <span className="deck__copy"><strong>{action.label}</strong><span>{action.outcome}</span></span>
          <span className="deck__state">{executing ? <span className="spinner"/> : done ? <Glyph check/> : <Glyph chevron/>}</span>
        </button>
      );
    })}
  </div>
  {lastAction && (
    <div className="deck__result" role="status">
      <span className="deck__result-label">Alexa+</span>
      <p>“{lastAction.spokenResponse}”</p>
    </div>
  )}
  <div className="deck__foot">
    <button className="button button--quiet deck__resolve" onClick={onResolve}>Care note & close <Glyph enter/></button>
    <span className="deck__hint">↑ ↓ move · Enter select · Back close</span>
  </div>
</div>
```

`disabled={executingAction !== null}` would disable all buttons including the focused one while executing. Fine. But if executingAction is set, navigation focus remains. Use `aria-busy`.

Remote.tsx:
Props:
```ts
interface RemoteProps { navigation: TvNavigation; onBack: () => void; sound: RoomToneController; disabled?: boolean; }
```
Markup:
```tsx
<div className="remote" aria-label="Fire TV remote">
  <div className="remote__top">
    <button className="remote__power" ... title="Room tone"><Glyph power/></button>
    <button className="remote__mic" ...><Glyph mic/></button>
  </div>
  <div className="remote__pad">
    <button className="remote__btn remote__btn--up" onClick={()=>navigation.move(-1)} aria-label="Up"><Glyph up/></button>
    ...
    <button className="remote__select" onClick={()=>navigation.select()} aria-label="Select"><span>OK</span></button>
  </div>
  <div className="remote__row">
    <button onClick={onBack}><Glyph back/><span>Back</span></button>
    <button onClick={sound.toggle}><Glyph sound/><span>Sound</span></button>
  </div>
</div>
```
Power button toggles sound? Better not; use a "sound" row. Power can be decorative/disabled with title "The TV is already on." But a disabled button is odd. Omit power. Keep mic? The mic isn't functional. Don't include non-functional controls. Include only D-pad, select, back, sound. The design doc mentions voice mic, but we shouldn't fake voice. Could include a mic button that triggers a short note "Voice input is not wired in this replay." via a callback. Hmm, adding fake buttons is bad. Skip mic. The remote is a navigation aid.

Add `data-tv-action` to select? The global key handler checks target closest `[data-tv-action]` on Enter to avoid double activation. For remote buttons, pressing Enter should trigger the remote button itself. Add `data-tv-action` to all remote buttons? Then Enter on a focused remote button triggers native click, and the global handler returns. Good. But the D-pad buttons are `<button>`; pressing Space also clicks. Fine.

