:root {
  color-scheme: dark;

  /* Surfaces — warm charcoal, never pure black */
  --bg-0: #070605;
  --bg-1: #0b0a08;
  --bg-2: #100e0b;
  --bg-3: #16120e;
  --surface: rgba(22, 18, 14, 0.72);
  --surface-solid: #15110d;

  /* Hairlines */
  --line: rgba(244, 231, 211, 0.1);
  --line-strong: rgba(244, 231, 211, 0.18);

  /* Ink */
  --ink: #f3ebdf;
  --ink-2: #cdc2b2;
  --ink-3: #9d9284;
  --ink-4: #72695f;

  /* Porch light */
  --amber: #f0a45c;
  --amber-bright: #ffc182;
  --amber-deep: #b86f35;
  --amber-soft: rgba(240, 164, 92, 0.12);

