  --ok: #8fb59a;
  --cool: #9fc0c7;
  --coral: #e08a6f;

  --focus: #ffc182;

  --font-display: "Newsreader Variable", "Iowan Old Style", Georgia, serif;
  --font-sans: "Instrument Sans Variable", "Helvetica Neue", Arial, sans-serif;
