20: function isTypingTarget(target: EventTarget | null): boolean {
21:   if (!(target instanceof HTMLElement)) return false;
22:   return /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName) || target.isContentEditable;
23: }
