25: /**
26:  * Roving D-pad focus for the care card. In the studio the keys only act while
27:  * focus is inside the living-room panel; on the Fire TV surface they are global.
28:  */
29: export function useTvNavigation({
30:   count,
31:   onBack,
32:   enabled = true,
33:   force = false,
34:   containerRef
35: }: TvNavigationOptions): TvNavigation {
36:   const [index, setIndexState] = useState(0);
37:   const buttons = useRef<Array<HTMLButtonElement | null>>([]);
38: 
39:   const setIndex = useCallback(
40:     (next: number) => {
41:       setIndexState(Math.max(0, Math.min(next, Math.max(0, count - 1))));
42:     },
43:     [count]
44:   );
45: 
46:   const registerAction = useCallback(
47:     (position: number) => (element: HTMLButtonElement | null) => {
48:       buttons.current[position] = element;
49:     },
50:     []
51:   );
52: 
53:   const focusIndex = useCallback(
54:     (next: number) => {
55:       if (count === 0) return;
56:       const bounded = ((next % count) + count) % count;
57:       setIndexState(bounded);
58:       const element = buttons.current[bounded];
59:       if (element) {
60:         element.focus({ preventScroll: true });
61:       }
62:     },
63:     [count]
64:   );
65: 
66:   const move = useCallback(
67:     (delta: number) => {
68:       if (count === 0) return;
69:       focusIndex(index + delta);
70:     },
71:     [count, focusIndex, index]
72:   );
73: 
74:   const select = useCallback(
75:     (position?: number) => {
76:       if (count === 0) return;
77:       const target = position ?? index;
78:       buttons.current[target]?.click();
79:     },
80:     [count, index]
81:   );
82: 
83:   useEffect(() => {
84:     setIndexState((current) => Math.min(current, Math.max(0, count - 1)));
85:   }, [count]);
86: 
87:   useEffect(() => {
88:     if (!enabled) return;
89: 
90:     const onKeyDown = (event: KeyboardEvent) => {
91:       if (count === 0 || isTypingTarget(event.target)) return;
92:       if (event.metaKey || event.ctrlKey || event.altKey) return;
93:       if (!force && !containerRef?.current?.contains(document.activeElement)) return;
94: 
95:       switch (event.key) {
96:         case "ArrowDown":
97:         case "ArrowRight":
98:           event.preventDefault();
99:           move(1);
100:           break;
101:         case "ArrowUp":
102:         case "ArrowLeft":
103:           event.preventDefault();
104:           move(-1);
105:           break;
106:         case "Enter": {
107:           if (event.target instanceof HTMLElement && event.target.closest("[data-tv-action]")) {
108:             return;
109:           }
110:           event.preventDefault();
111:           select();
112:           break;
113:         }
114:         case "Escape":
115:         case "Backspace":
116:           event.preventDefault();
117:           onBack();
118:           break;
119:         case "1":
120:         case "2":
121:         case "3": {
122:           const position = Number(event.key) - 1;
123:           if (position >= count) return;
124:           event.preventDefault();
125:           focusIndex(position);
126:           select(position);
127:           break;
128:         }
129:         default:
130:           break;
131:       }
132:     };
133: 
134:     window.addEventListener("keydown", onKeyDown);
135:     return () => window.removeEventListener("keydown", onKeyDown);
136:   }, [containerRef, count, enabled, focusIndex, force, move, onBack, select]);
137: 
138:   return {
139:     index,
140:     setIndex,
141:     registerAction,
142:     move,
143:     select,
144:     focusIndex
145:   };
146: }

