15:   const buffer = context.createBuffer(1, context.sampleRate * seconds, context.sampleRate);
16:   const data = buffer.getChannelData(0);
17:   let last = 0;
18:   for (let index = 0; index < data.length; index += 1) {
19:     const white = Math.random() * 2 - 1;
20:     last = (last + 0.018 * white) / 1.018;
21:     data[index] = last * 3.2;
22:   }
23:   return buffer;
24: }
