5: ## Task 1: Create Root `LICENSE` (MIT) and Open-Source Package `packages/ring-alexa-mcp-bridge/src/index.ts`
6: Write `packages/ring-alexa-mcp-bridge/src/index.ts` with timing-safe Ring HMAC-SHA256 verification, RFC 8829 WHEP SDP negotiation, and Alexa+ MCP Apps Card builder:
7: 
8: ```typescript
9: import crypto from 'node:crypto';
10: 
11: export interface RingWebhookEvent {
12:   data: {
13:     id: string;
14:     type: 'motion_detected' | 'ding' | 'person_detected';
15:     attributes: {
16:       device_id: string;
17:       timestamp: string;
18:       classification: 'human' | 'package' | 'vehicle' | 'animal';
19:       confidence: number;
20:       zone: string;
21:       scenario_id?: 'SCN-01' | 'SCN-02' | 'SCN-03';
22:     };
23:   };
24: }
25: 
26: export function computeRingHmacSignature(rawBody: string, secret: string, timestamp: string): string {
27:   const payload = `${timestamp}.${rawBody}`;
28:   const hex = crypto.createHmac('sha256', secret).update(payload, 'utf8').digest('hex');
29:   return `sha256=${hex}`;
30: }
31: 
32: export function verifyRingWebhookHmac(
33:   rawBody: string,
34:   signatureHeader: string | undefined,
35:   timestampHeader: string | undefined,
36:   secret: string,
37:   maxSkewSeconds = 300
38: ): { valid: boolean; reason?: string } {
39:   if (!signatureHeader || !timestampHeader) {
40:     return { valid: false, reason: 'Missing X-Ring-Signature or X-Ring-Timestamp header' };
41:   }
42:   const ts = Number(timestampHeader);
43:   if (Number.isNaN(ts) || Math.abs(Math.floor(Date.now() / 1000) - ts) > maxSkewSeconds) {
44:     return { valid: false, reason: 'Webhook timestamp outside allowable 300s replay window' };
45:   }
46:   const expected = computeRingHmacSignature(rawBody, secret, timestampHeader);
47:   const expectedBuf = Buffer.from(expected, 'utf8');
48:   const receivedBuf = Buffer.from(signatureHeader, 'utf8');
49:   if (expectedBuf.length !== receivedBuf.length || !crypto.timingSafeEqual(expectedBuf, receivedBuf)) {
50:     return { valid: false, reason: 'HMAC-SHA256 digest mismatch' };
51:   }
52:   return { valid: true };
53: }
54: 
55: export interface WhepSessionResult {
56:   sessionId: string;
57:   whepEndpoint: string;
58:   sdpAnswer: string;
59:   mode: 'live_ava_api' | 'simulator_loopback';
60: }
61: 
62: export async function negotiateRingWhepSession(
63:   deviceId: string,
64:   sdpOffer: string,
65:   bearerToken?: string
66: ): Promise<WhepSessionResult> {
67:   const whepEndpoint = `https://api.amazonvision.com/v1/devices/${encodeURIComponent(deviceId)}/media/streaming/whep/sessions`;
68:   if (bearerToken && bearerToken !== 'SIMULATOR_TOKEN') {
69:     const res = await fetch(whepEndpoint, {
70:       method: 'POST',
71:       headers: {
72:         Authorization: `Bearer ${bearerToken}`,
73:         'Content-Type': 'application/sdp',
74:       },
75:       body: sdpOffer,
76:     });
77:     if (res.status === 201) {
78:       const sdpAnswer = await res.text();
79:       const location = res.headers.get('location') || `${whepEndpoint}/live-session`;
80:       return { sessionId: location.split('/').pop() || 'live-session', whepEndpoint: location, sdpAnswer, mode: 'live_ava_api' };
81:     }
82:   }
83:   // Deterministic WHEP Simulator Loopback for zero-hardware hackathon judging
84:   return {
85:     sessionId: `whep_sim_${deviceId}_${Date.now()}`,
86:     whepEndpoint,
87:     sdpAnswer: `v=0\r\no=- ${Date.now()} 2 IN IP4 127.0.0.1\r\ns=RingAVA-WHEP-Sim\r\nt=0 0\r\nm=video 9 UDP/TLS/RTP/SAVPF 96\r\na=rtpmap:96 H264/90000\r\na=sendonly\r\n`,
88:     mode: 'simulator_loopback',
89:   };
90: }
91: 
92: export interface AlexaMcpAppCard {
93:   type: 'AlexaMcpAppCard';
94:   version: '2025-11-25';
95:   scenarioId: string;
96:   severity: 'CRITICAL_CARE' | 'ACCESSIBILITY_RELAY' | 'COLD_CHAIN_CUSTODY';
97:   title: string;
98:   subtitle: string;
99:   spokenAlexaPrompt: string;
100:   beeContextFact: string;
101:   fireTvHudActions: Array<{
102:     id: string;
103:     label: string;
104:     dpadKey: '1' | '2' | '3';
105:     alexaCommand: string;
106:   }>;
107: }
108: 
109: export function buildAlexaMcpCardPayload(card: AlexaMcpAppCard) {
