75: /**
76:  * Verify a Ring-style webhook in constant time.
77:  *
78:  * The signature covers `<timestamp>.<raw body>`, which prevents a captured
79:  * payload from being re-used after the replay window has elapsed.
80:  */
81: export function verifyRingWebhookHmac(
82:   rawBody: string,
83:   signatureHeader: string | undefined,
84:   timestampHeader: string | undefined,
85:   secret: string,
86:   maxSkewSeconds = 300
87: ): { valid: boolean; reason?: string } {
88:   if (!signatureHeader || !timestampHeader) {
89:     return { valid: false, reason: "Missing X-Ring-Signature or X-Ring-Timestamp header" };
90:   }
91:   if (!/^sha256=[a-f0-9]{64}$/i.test(signatureHeader)) {
92:     return { valid: false, reason: "Malformed X-Ring-Signature header" };
93:   }
94:   const timestamp = Number(timestampHeader);
95:   if (!Number.isFinite(timestamp) || !/^\d{9,12}$/.test(timestampHeader)) {
96:     return { valid: false, reason: "Invalid X-Ring-Timestamp header" };
97:   }
98:   const nowSeconds = Math.floor(Date.now() / 1000);
99:   if (Math.abs(nowSeconds - timestamp) > maxSkewSeconds) {
100:     return { valid: false, reason: "Webhook timestamp outside the 300s replay window" };
101:   }
102:   const expected = computeRingHmacSignature(rawBody, secret, timestampHeader);
103:   const expectedBuffer = Buffer.from(expected, "utf8");
104:   const receivedBuffer = Buffer.from(signatureHeader, "utf8");
105:   if (
106:     expectedBuffer.length !== receivedBuffer.length ||
107:     !crypto.timingSafeEqual(expectedBuffer, receivedBuffer)
108:   ) {
109:     return { valid: false, reason: "HMAC-SHA256 digest mismatch" };
110:   }
111:   return { valid: true };
112: }
