import { chromium } from "playwright";
import fs from "node:fs";

const outDir = "C:/Users/dabhi/AppData/Local/Temp/opencode/hearthguard-shots";
fs.mkdirSync(outDir, { recursive: true });

const browser = await chromium.launch();
const logs = [];

async function shoot(name, url, viewport, waitMs = 2500, fullPage = true) {
  const context = await browser.newContext({ viewport, deviceScaleFactor: 1 });
  const page = await context.newPage();
  page.on("console", (msg) => {
    if (msg.type() === "error" || msg.type() === "warning") {
      logs.push({ page: name, type: msg.type(), text: msg.text() });
    }
  });
  page.on("pageerror", (err) => logs.push({ page: name, type: "pageerror", text: String(err) }));
  await page.goto(url, { waitUntil: "networkidle", timeout: 30000 });
  await page.waitForTimeout(waitMs);
  const path = `${outDir}/${name}.png`;
  await page.screenshot({ path, fullPage });
  const metrics = await page.evaluate(() => ({
    title: document.title,
    scrollWidth: document.documentElement.scrollWidth,
    clientWidth: document.documentElement.clientWidth,
    scrollHeight: document.documentElement.scrollHeight,
    bodyText: document.body.innerText.slice(0, 500),
  }));
  await context.close();
  return { name, path, metrics };
}

const results = [];
results.push(await shoot("studio-1600", "http://localhost:5173/?empty=1", { width: 1600, height: 1000 }, 1500));
results.push(await shoot("studio-1440", "http://localhost:5173/", { width: 1440, height: 900 }, 4500));
results.push(await shoot("studio-390", "http://localhost:5173/?empty=1", { width: 390, height: 844 }, 1500));
results.push(await shoot("firetv-1920", "http://localhost:5173/?mode=firetv&scenario=SCN-02", { width: 1920, height: 1080 }, 4500, false));

console.log(JSON.stringify({ results, logs }, null, 2));
await browser.close();

