265: export async function handleMcpPost(req: Request, res: Response): Promise<void> {
266:   const headerSession = req.headers["mcp-session-id"];
267:   const sessionId = Array.isArray(headerSession) ? headerSession[0] : headerSession;
268: 
269:   if (sessionId) {
270:     const transport = mcpSessions.get(sessionId);
271:     if (!transport) {
272:       res.status(404).json(errorBody("Unknown or expired MCP session"));
273:       return;
274:     }
275:     await transport.handleRequest(req, res, req.body);
276:     return;
277:   }
278: 
279:   const transport = new StreamableHTTPServerTransport({
280:     sessionIdGenerator: randomUUID,
281:     enableJsonResponse: true,
282:     retryInterval: 2000,
283:     onsessioninitialized: (newSessionId) => {
284:       mcpSessions.set(newSessionId, transport);
285:     },
286:     onsessionclosed: (closedSessionId) => {
287:       mcpSessions.delete(closedSessionId);
288:     }
289:   });
290: 
291:   const server = createProtocolServer();
292:   await server.connect(transport);
293: 
294:   const previousClose = transport.onclose;
295:   const unsubscribe = careEvents.subscribe((event) => {
296:     if (event.type === "incident.created" || event.type === "intervention.executed") {
297:       void server.server.sendResourceUpdated({ uri: "care://timeline" }).catch(() => undefined);
298:     }
299:   });
300:   transport.onclose = () => {
301:     previousClose?.();
302:     unsubscribe();
303:   };
304: 
305:   await transport.handleRequest(req, res, req.body);
306: }
